  const startMonth = 2; // February
  const endMonth = 2; // February

  const startYear_avg = 2010;
  const endYear_avg = 2020;
  const targetYear = 2021;

  // Function to mask clouds from Landsat SR data (Collection 2, Level 2)
  function maskL45789sr(image) {
    const qaPixel = image.select('QA_PIXEL');
    // Bits 3 and 5 are cloud shadow and cloud, respectively.
    // Bits 3, 5, 7, 9, 11 (cloud shadow, cloud, snow, water, cirrus for L8/9)
    // More robust mask:
    // Bits 2, 3, 4, 5 for L4-7 (cloud confidence, cloud shadow, snow, cloud)
    // Bits 2, 3, 4, 5, 6, 7, 8, 9 for L8-9 (dilated cloud, cloud shadow, cloud confidence, cloud, cirrus)
    const cloudShadowBit = 3;
    const cloudBit = 5;
    const snowBit = 4; // L4-7
    const waterBit = 7; // L8-9
    const cirrusBit = 9; // L8-9

    const dilatedCloudBit = 1; // L8-9
    const cloudConfidenceBit = 2; // L4-9

    // Cloud shadow and cloud bits
    const cloudShadow = qaPixel.getBit(cloudShadowBit);
    const cloud = qaPixel.getBit(cloudBit);

    // Get the cloud confidence (L4-9) - 0: None, 1: Low, 2: Medium, 3: High
    const cloudConfidence = qaPixel.select('QA_PIXEL').rightShift(cloudConfidenceBit).bitwiseAnd(3); // Bits 2-3

    // Conditions to mask: cloud shadow OR (medium/high cloud confidence) OR (snow/cirrus for L8/9)
    const isCloud = cloud.eq(1).or(cloudShadow.eq(1)).or(cloudConfidence.gt(1)); // >1 means medium or high confidence

    return image.updateMask(isCloud.not());
  }

  // Function to calculate NDVI for Landsat SR data
  function addNDVI(image) {
    let nir, red;
    const platform = image.get('SPACECRAFT_ID');

    if (platform === 'LANDSAT_8' || platform === 'LANDSAT_9') {
      nir = 'SR_B5';
      red = 'SR_B4';
    } else if (platform === 'LANDSAT_7' || platform === 'LANDSAT_5') {
      nir = 'SR_B4';
      red = 'SR_B3';
    } else {
      // Handle other Landsat platforms if necessary, or throw an error.
      return image.addBands(ee.Image(-999).rename('NDVI')); // Placeholder for unsupported
    }

    // Apply scaling factor for surface reflectance bands (0.0000275 * DN - 0.2)
    // Add 0.1 to account for 0.0000275 * DN + 0.1 for radiance
    // The SR_Bands are already scaled to 0-1, but the original Landsat L2 guide suggests
    // (pixel_value * 0.0000275) - 0.2. Let's apply this scaling here.
    const scaledNir = image.select(nir).multiply(0.0000275).add(-0.2);
    const scaledRed = image.select(red).multiply(0.0000275).add(-0.2);

    const ndvi = scaledNir.subtract(scaledRed).divide(scaledNir.add(scaledRed)).rename('NDVI');
    return image.addBands(ndvi);
  }

