  function getLandsatCollection(startYear, endYear, month, geom) {
    const ls8_9_col = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .merge(ee.ImageCollection('LANDSAT/LC09/C02/T1_L2'));
    const ls7_col = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2');
    const ls5_col = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2');

    const combined = ls5_col.merge(ls7_col).merge(ls8_9_col);

    return combined
      .filterBounds(geom)
      .filter(ee.Filter.calendarRange(startYear, endYear, 'year'))
      .filter(ee.Filter.calendarRange(month, month, 'month'))
      .map(maskL45789sr)
      .map(addNDVI)
      .select('NDVI');
  }

  // 2. Data Acquisition & Check
  const avg_collection = getLandsatCollection(startYear_avg, endYear_avg, startMonth, aoi);
  const target_collection = getLandsatCollection(targetYear, targetYear, startMonth, aoi);

  const avg_size = await avg_collection.size().getInfo();
  const target_size = await target_collection.size().getInfo();

  console.log(`Reference Period (2010-2020 Feb) Images: ${avg_size}`);
  console.log(`Target Period (2021 Feb) Images: ${target_size}`);

  if (avg_size === 0 || target_size === 0) {
    console.log("Not enough images for one or both periods after initial filtering.");
    console.log("C1");
    return;
  }

  // Calculate the mean NDVI for each collection
  const scale = 30; // Landsat native resolution
  const maxPixels = 1e9;

  // Function to calculate mean NDVI and pixel count for a collection
  async function calculateMeanNDVI(collection, name) {
    const meanNDVI = collection.mean();

    if (meanNDVI === null) {
      console.log(`${name} mean calculation failed (returned null).`);
      return { mean: null, pixels: 0 };
    }

    const ndviStats = await meanNDVI.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: aoi,
      scale: scale,
      maxPixels: maxPixels
    }).getInfo();

    const mean = ndviStats ? ndviStats.NDVI_mean : null;
    const pixels = ndviStats ? ndviStats.NDVI_count : 0;

    return { mean: mean, pixels: pixels };
  }

  const avg_stats = await calculateMeanNDVI(avg_collection, 'Reference Period');
  const target_stats = await calculateMeanMeanNDVI(target_collection, 'Target Period');

  const avg_ndvi = avg_stats.mean;
  const avg_pixels = avg_stats.pixels;
  const target_ndvi = target_stats.mean;
  const target_pixels = target_stats.pixels;

  console.log(`Ref NDVI (2010-2020 Feb): ${avg_ndvi !== null ? avg_ndvi.toFixed(3) : 'N/A'}, Pixels: ${avg_pixels}`);
  console.log(`Target NDVI (2021 Feb): ${target_ndvi !== null ? target_ndvi.toFixed(3) : 'N/A'}, Pixels: ${target_pixels}`);

  if (avg_pixels === 0 || target_pixels === 0) {
    console.log("No valid pixels remain after cloud masking/processing for one or both periods.");
    console.log("C2");
    return;
  }

  if (avg_ndvi === null || isNaN(avg_ndvi) || target_ndvi === null || isNaN(target_ndvi)) {
    console.log("NDVI calculation resulted in None/NaN for one or both periods.");
    console.log("C3");
    return;
  }

  // 5. Validation & Final Answer
  if (target_ndvi > avg_ndvi) {
    console.log("A");
  } else {
    console.log("B");
  }
}

